INSERT IGNORE INTO m_permission (`grouping`, code, entity_name, action_name, can_maker_checker)
VALUES ('portfolio', 'APPROVE_KYCDOCUMENT', 'KYCDOCUMENT', 'APPROVE', 0);

INSERT IGNORE INTO m_permission (`grouping`, code, entity_name, action_name, can_maker_checker)
VALUES ('portfolio', 'REJECT_KYCDOCUMENT', 'KYCDOCUMENT', 'REJECT', 0);

INSERT IGNORE INTO m_permission (`grouping`, code, entity_name, action_name, can_maker_checker)
VALUES ('portfolio', 'SUBMIT_KYCDOCUMENT', 'KYCDOCUMENT', 'SUBMIT', 0);

INSERT IGNORE INTO m_role_permission (role_id, permission_id)
SELECT 1, p.id FROM m_permission p WHERE p.code = 'APPROVE_KYCDOCUMENT'
AND NOT EXISTS (SELECT 1 FROM m_role_permission rp WHERE rp.role_id = 1 AND rp.permission_id = p.id);

INSERT IGNORE INTO m_role_permission (role_id, permission_id)
SELECT 1, p.id FROM m_permission p WHERE p.code = 'REJECT_KYCDOCUMENT'
AND NOT EXISTS (SELECT 1 FROM m_role_permission rp WHERE rp.role_id = 1 AND rp.permission_id = p.id);

INSERT IGNORE INTO m_role_permission (role_id, permission_id)
SELECT 1, p.id FROM m_permission p WHERE p.code = 'SUBMIT_KYCDOCUMENT'
AND NOT EXISTS (SELECT 1 FROM m_role_permission rp WHERE rp.role_id = 1 AND rp.permission_id = p.id);
